Post Date: 2014-12-24T07:27:42Z
Current Date: April 4 2025
Title: BOOLEAN field not updating when passed a string 'true' or 'false' (Postgres)
Description: I have the following model: 

``` javascript
"use strict";

module.exports = function(sequelize, DataTypes) {
  var Program = sequelize.define("Program", {
    name: {
      type: DataTypes.STRING,
      allowNull: false
    },
    short_name: DataTypes.STRING,
    description: DataTypes.STRING,
    short_description: DataTypes.STRING,
    fitness_level: {
      type: DataTypes.ENUM('average', 'good', 'high'),
      defaultValue: 'average'
    },
    prerequisites: DataTypes.ARRAY(DataTypes.STRING),
    knowledge_skills_equipment: DataTypes.ARRAY(DataTypes.STRING),
    premium_activity: {
      type: DataTypes.BOOLEAN,
      defaultValue: false
    },
    location: {
      type: DataTypes.ENUM('onsite', 'offsite'),
      defaultValue: 'onsite',
      allowNull: false
    },
    program_periods_available: DataTypes.INTEGER,
    max_participants_per_period: DataTypes.INTEGER,
    program_periods_required: {
      type: DataTypes.INTEGER,
      defaultValue: 1,
      validate: { min: 1, max: 3 },
      allowNull: false
    },
    fee: {
      type: DataTypes.FLOAT,
      defaultValue: 0.00
    },
    hidden: {
      type: DataTypes.BOOLEAN,
      defaultValue: true,
      allowNull: false
    },
    oos_required: {
      type: DataTypes.INTEGER,
      defaultValue: 0,
      allowNull: false
    }
  }, {
    underscored: true,
    classMethods: {
      associate: function(models) {
        Program.hasMany(models.OOS, { as: 'OOS', through: 'program_oos_assignments' })
      }
    }
  });

  return Program;
};
```

If I pass a boolean literal to `Instance#updateAttributes`, the value gets updated successfully:

``` javascript
models.Program.find(1).then(function(record) { record.updateAttributes( {hidden: true} ) })
```

SQL Generated:

``` sql
Executing (default): SELECT "id", "name", "short_name", "description", "short_description", "fitness_level", "prerequisites", "knowledge_skills_equipment", "premium_activity", "location", "program_periods_available", "max_participants_per_period", "program_periods_required", "fee", "hidden", "oos_required", "created_at", "updated_at" FROM "Programs" AS "Program" WHERE "Program"."id"=1;
Executing (default): UPDATE "Programs" SET "hidden"=true,"updated_at"='2014-12-24 07:17:01.762 +00:00' WHERE "id"=1 RETURNING *
```

If I pass in a string value of 'true' or 'false' (as might be received in a form POST), I get some weird behaviour:

``` javascript
models.Program.find(1).then(function(record) { record.updateAttributes( {hidden: 'true'} ) })
```

SQL Generated: 

``` sql
Executing (default): SELECT "id", "name", "short_name", "description", "short_description", "fitness_level", "prerequisites", "knowledge_skills_equipment", "premium_activity", "location", "program_periods_available", "max_participants_per_period", "program_periods_required", "fee", "hidden", "oos_required", "created_at", "updated_at" FROM "Programs" AS "Program" WHERE "Program"."id"=1;
Executing (default): UPDATE "Programs" SET "hidden"=false,"updated_at"='2014-12-24 07:18:01.253 +00:00' WHERE "id"=1 RETURNING *
```

In this case, setting `hidden` to `'true'` (or any string value, for that matter) resulted in it being set to `false`.

I've tried using a setter method on the `hidden` field to cast the string to a boolean:

``` javascript
function castStringToBoolean(value) {
  var ret;
  if (value === 'true') {
    ret = true;
  } else {
    ret = false;
  }
  return ret;
}
```

With this setter in place, nothing at all is set for the `hidden` field:

``` javascript
models.Program.find(1).then(function(record) { record.updateAttributes( {hidden: 'true'} ) })
```

SQL Generated:

``` sql
Executing (default): SELECT "id", "name", "short_name", "description", "short_description", "fitness_level", "prerequisites", "knowledge_skills_equipment", "premium_activity", "location", "program_periods_available", "max_participants_per_period", "program_periods_required", "fee", "hidden", "oos_required", "created_at", "updated_at" FROM "Programs" AS "Program" WHERE "Program"."id"=1;
Executing (default): UPDATE "Programs" SET "updated_at"='2014-12-24 07:20:49.153 +00:00' WHERE "id"=1 RETURNING *
```

If I cast the field to a boolean before sending it to `updateAttributes` (e.g. in my Express route handler), then it works:

``` javascript
if (req.body.hasOwnProperty('hidden') && typeof req.body.hidden === 'string') {
    req.body.hidden = req.body.hidden === 'true' ? true : false
}
```

What is the proper way of handling booleans in Seqelize? Why is the setter method not working as I think it should?


